const item = $input.first().json || {};
const headers = item.headers || {};
const body = item.body && typeof item.body === 'object' ? item.body : item;

const expectedKey =
  typeof $env !== 'undefined' && $env
    ? $env.N8N_API_KEY || $env.N8N_WEBHOOK_SECRET || ''
    : '';
const providedKey =
  headers['x-n8n-api-key'] ||
  headers['X-N8N-API-KEY'] ||
  '';

const executionId = typeof body.executionId === 'string' ? body.executionId.trim() : '';
const enrollmentId = typeof body.enrollmentId === 'string' ? body.enrollmentId.trim() : '';
const stepId = typeof body.stepId === 'string' ? body.stepId.trim() : '';
const correlationId =
  (typeof headers['x-correlation-id'] === 'string' && headers['x-correlation-id'].trim()) ||
  (typeof body.correlationId === 'string' && body.correlationId.trim()) ||
  executionId ||
  null;

const errors = [];
if (expectedKey && (!providedKey || providedKey !== expectedKey)) {
  errors.push('Invalid follow-up webhook credentials');
}
if (!executionId) {
  errors.push('Missing executionId');
}
if (!enrollmentId) {
  errors.push('Missing enrollmentId');
}
if (!stepId) {
  errors.push('Missing stepId');
}

const isUnauthorized = errors.includes('Invalid follow-up webhook credentials');

return [
  {
    json: {
      isValidRequest: errors.length === 0,
      statusCode: isUnauthorized ? 401 : errors.length > 0 ? 400 : 200,
      validationError:
        errors.length > 0
          ? errors.join('; ')
          : null,
      executionId: executionId || null,
      enrollmentId: enrollmentId || null,
      stepId: stepId || null,
      correlationId,
      validatedAt: new Date().toISOString()
    }
  }
];

