const req = $input.first().json;
// Enforce PR #72 boundary: n8n forwards only the persisted execution identity.
// Recipient, subject and rendered template content remain authoritative in NestJS.
return [
  {
    json: {
      executionId: req.executionId,
      enrollmentId: req.enrollmentId,
      stepId: req.stepId,
      idempotencyKey: req.executionId,
      correlationId: req.correlationId || req.executionId,
      dispatchedAt: new Date().toISOString()
    }
  }
];

const res = $input.first().json || {};
const ctx = $('Code: Prepare Idempotent Send Handoff').first().json;

const rawStatus = typeof res.deliveryStatus === 'string' ? res.deliveryStatus : (res.success === true ? 'SENT' : 'UNKNOWN');
const isSent = res.success === true && rawStatus === 'SENT';
const isUnknown = rawStatus === 'UNKNOWN';
const isRetryableFailure = rawStatus === 'RETRYABLE_FAILURE';

return [
  {
    json: {
      success: isSent,
      deliveryStatus: rawStatus,
      providerMessageId: res.providerMessageId ?? null,
      error: isSent ? null : (res.error || (isUnknown ? 'DELIVERY_OUTCOME_UNKNOWN' : 'Follow-up delivery failed')),
      retryable: isSent || isUnknown ? false : Boolean(isRetryableFailure || res.retryable === true),
      idempotencyStatus: res.idempotencyStatus || 'new',
      statusCode: 200,
      executionId: ctx.executionId,
      enrollmentId: ctx.enrollmentId,
      stepId: ctx.stepId,
      correlationId: ctx.correlationId
    }
  }
];

const err = $input.first().json || {};
const ctx = $('Code: Prepare Idempotent Send Handoff').first().json;

const statusCode = Number(
  err.error?.status ||
  err.details?.httpCode ||
  err.error?.statusCode ||
  err.statusCode ||
  502
);

const isExplicitRetryableHttp = [408, 423, 425, 429].includes(statusCode);
const isAmbiguousServerFailure = statusCode >= 500;
const deliveryStatus = isExplicitRetryableHttp
  ? 'RETRYABLE_FAILURE'
  : isAmbiguousServerFailure
    ? 'UNKNOWN'
    : 'PERMANENT_FAILURE';

return [
  {
    json: {
      success: false,
      deliveryStatus,
      providerMessageId: null,
      error:
        err.error?.message ||
        err.message ||
        (isAmbiguousServerFailure ? 'DELIVERY_OUTCOME_UNKNOWN' : 'Follow-up delivery request failed'),
      retryable: isExplicitRetryableHttp || isAmbiguousServerFailure,
      idempotencyStatus: 'new',
      statusCode,
      executionId: ctx.executionId,
      enrollmentId: ctx.enrollmentId,
      stepId: ctx.stepId,
      correlationId: ctx.correlationId
    }
  }
];

const item = $input.first().json || {};
const isPersistedUnknown =
  item.deliveryStatus === 'UNKNOWN' && Number(item.statusCode || 200) === 200;

return [
  {
    json: {
      success: false,
      deliveryStatus: item.deliveryStatus || 'FAILED',
      providerMessageId: item.providerMessageId ?? null,
      error:
        item.error ||
        (item.deliveryStatus === 'UNKNOWN'
          ? 'DELIVERY_OUTCOME_UNKNOWN'
          : 'Follow-up delivery request failed'),
      retryable: isPersistedUnknown ? false : Boolean(item.retryable),
      idempotencyStatus: item.idempotencyStatus || 'new',
      statusCode: Number(item.statusCode || 200),
      executionId: item.executionId || null,
      enrollmentId: item.enrollmentId || null,
      stepId: item.stepId || null,
      correlationId: item.correlationId || null
    }
  }
];
